# Imports
print("Importing Libraries")
import math
import sys 
from PySide6.QtWidgets import(
        
        QApplication, 
        QWidget,
        QVBoxLayout,
        QLineEdit,
        QPushButton,
        QMessageBox,
        QLabel
)


# UI Setup
qapp = QApplication(sys.argv)

window = QWidget()
window.setWindowTitle("Galaxy Dynamics v0.2[BETA]")
window.setGeometry(100, 100, 400, 300)

layout = QVBoxLayout()
# Variables
Mercury = 3.7
Venus = 8.87
Earth = 9.81
Mars = 3.71
Jupiter = 24.79
Saturn = 10.44
Uranus = 8.69
Neptune = 11.15
Moon = 1.62
Pluto = 0.62

# UI Buildout

isp_input = QLineEdit()
isp_input.setPlaceholderText("Enter ISP (s)")
layout.addWidget(isp_input)

g0_input = QLineEdit()
g0_input.setPlaceholderText("Enter g0 (m/s²)")
layout.addWidget(g0_input)

m0_input = QLineEdit()
m0_input.setPlaceholderText("Enter initial mass (kg)")
layout.addWidget(m0_input)

m1_input = QLineEdit() 
m1_input.setPlaceholderText("Enter final mass (kg)")
layout.addWidget(m1_input)

submit_button = QPushButton("Calculate ΔV")
# wehn clicked, call the calculate_DeltaV function and display the result in a message box
def calculate_DeltaV(isp, g0, m0, m1):
    if m0 <= 0 or m1 <= 0 or isp <= 0 or g0 <= 0:
        QMessageBox.critical(None, "Error", "All fields must be filled.")
        return None
    delta_v = isp * g0 * math.log(m0 / m1)
    QMessageBox.information(None, "Result", f"ΔV: {delta_v:.2f} m/s")
    return delta_v
 
def calculate():
    isp = float(isp_input.text())
    g0 = float(g0_input.text())
    m0 = float(m0_input.text())
    m1 = float(m1_input.text())

    delta_v = calculate_DeltaV(isp, g0, m0, m1)

    return calculate


submit_button.clicked.connect(calculate)
layout.addWidget(submit_button)


window.setLayout(layout)
window.show()

sys.exit(qapp.exec())
 